contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount, "not enough balance");

        uint256 depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;

        c.withdrawAll(); if (__ESBMC_reverted()) return;

        assert(
            c.depositsCount() == depositsBefore &&
            c.owner() == ownerBefore &&
            address(c).balance == 0
        );
    }
}

